import { Container, makeStyles, Typography } from "@material-ui/core";
import Carousel from "./Carousel";
import { useTheme } from "../../ThemeContext";

const useStyles = makeStyles((theme) => ({
  bannerDark: {
    backgroundColor: "#050505",
    borderBottom: "1px solid #333",
  },
  bannerLight: {
    backgroundColor: "#fafafa",
    borderBottom: "1px solid #eee",
  },
  bannerContent: {
    height: 480,
    display: "flex",
    flexDirection: "column",
    paddingTop: 45,
    justifyContent: "space-around",
  },
  tagline: {
    display: "flex",
    height: "40%",
    flexDirection: "column",
    justifyContent: "center",
    textAlign: "center",
  },
  titleDark: {
    color: "#fff",
    fontFamily: "serif",
    fontWeight: 800,
    letterSpacing: "2px",
    textTransform: "uppercase",
  },
  titleLight: {
    color: "#000",
    fontFamily: "serif",
    fontWeight: 800,
    letterSpacing: "2px",
    textTransform: "uppercase",
  },
  subtitleDark: {
    color: "#888",
    marginTop: 15,
    fontFamily: "serif",
    fontSize: "1.1rem",
    letterSpacing: "0.5px",
  },
  subtitleLight: {
    color: "#666",
    marginTop: 15,
    fontFamily: "serif",
    fontSize: "1.1rem",
    letterSpacing: "0.5px",
  },
}));

function Banner() {
  const classes = useStyles();
  const { isDarkMode } = useTheme();

  return (
    <div className={isDarkMode ? classes.bannerDark : classes.bannerLight}>
      <Container className={classes.bannerContent}>
        <div className={classes.tagline}>
          <Typography
            variant="h2"
            className={isDarkMode ? classes.titleDark : classes.titleLight}
          >
            Crypto Tracker
          </Typography>
          <Typography
            variant="subtitle2"
            className={isDarkMode ? classes.subtitleDark : classes.subtitleLight}
          >
            Live Market Updates • Advanced Data Aggregation • Unbiased Analysis
          </Typography>
        </div>
        <Carousel />
      </Container>
    </div>
  );
}

export default Banner;
